var _DP_JV = null, _DP_BK = null, _DP_CH = null;
var _DP_ILLU_DIAG = '';   
function _dpSetCtx(jv, bk, ch) {
    try { if (jv) _DP_JV = jv; } catch (e1) {}
    try { if (bk) _DP_BK = bk; } catch (e2) {}
    try { if (ch) _DP_CH = ch; } catch (e3) {}
    return _DP_JV;
}
function _dpScopeChapter() {
    try { if (typeof chapter !== 'undefined' && chapter) return chapter; } catch (e1) {}
    try { if (_DP_CH) return _DP_CH; } catch (e2) {}
    return null;
}
function _dpJv(jv) {
    if (jv) return jv;
    if (_DP_JV) return _DP_JV;
    try { if (typeof java !== 'undefined' && java) return java; } catch (e1) {}
    try { if (typeof source !== 'undefined' && source) return source; } catch (e2) {}
    return null;
}

var _DP_UA = 'Mozilla/5.0 (Linux; Android 12; Redmi K40 Build/SKQ1.220213.001; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/110.0.0.0 Mobile Safari/537.36';
var _DP_LANG = 'zh-CN,zh;q=0.9';
var _DP_QD_DIAG = '';
var _DP_DEBUG = true;          
var _DP_DEBUG_OK = false;      
var _DP_NET_ERR = '';          
var _DP_CSRF = '';             
var _DP_LAST_FAIL = '';        
var _DP_HOT_EMPTY = false;
var _DP_HOT_DIAG = '';
var _DP_IMG_VH = 55;

var _DP_SERVER = 'http://43.139.147.103:8070';   

function _dpSrv() {
    try {
        var sc = _dpSrcOf(_dpJv());
        if (sc && typeof sc.get === 'function') {
            var v = String(sc.get('agg_server') || '').replace(/\/+$/, '');
            if (v) return v;
        }
    } catch (e0) {}
    return _DP_SERVER;
}
var _dpBidCache = {};          
var _dpCatCache = {};          

function _dpFlat(s) {
    try { s = String(s == null ? '' : s); } catch (e0) { s = ''; }
    try { s = s.split('').join(''); } catch (e1) {}
    return s;
}
function _dpFlatHd(hd) {
    var out = {};
    try { for (var k in hd) { out[_dpFlat(k)] = _dpFlat(hd[k]); } } catch (e) { return hd; }
    return out;
}

function _dpToast(jav, msg) {
    if (!_DP_DEBUG) return;
    try { jav.toast(msg); } catch (e) {}
}

function _dpT2S(jav, s) {
    var v = String(s == null ? '' : s);
    if (!v) return v;
    try { var r = jav.t2s(v); if (r) return String(r); } catch (e) {}
    return v;
}
function _dpGetJson(jav, url, headers) {
    try {
        var r = jav.get(url, headers);
        var body = String(r.body() || '');
        if (!body) return null;
        return JSON.parse(body);
    } catch (e) { _DP_NET_ERR = String(e); return null; }
}
function _dpIsHtmlBlock(t) {
    return /<(p|br|div|h[1-6])[\s>\/]/i.test(String(t == null ? '' : t));
}

function _dpPlainText(s) {
    return String(s == null ? '' : s)
        .replace(/<script[\s\S]*?<\/script>/gi, '')
        .replace(/<style[\s\S]*?<\/style>/gi, '')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/p>/gi, '\n')
        .replace(/<\/div>/gi, '\n')
        .replace(/<[^>]*>/g, '')
        .replace(/&nbsp;/gi, ' ')
        .replace(/&ldquo;/gi, '“').replace(/&rdquo;/gi, '”')
        .replace(/&hellip;/gi, '…').replace(/&mdash;/gi, '—')
        .replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"')
        .replace(/&#\d+;/g, ' ');
}
function _dpInjectServer(t, nm, au, cn, jav) {
    try {
        var plain = _dpIsHtmlBlock(t) ? _dpPlainText(t) : t;
        var body = 'name=' + encodeURIComponent(nm)
                 + '&author=' + encodeURIComponent(au)
                 + '&chapter=' + encodeURIComponent(cn)
                 + '&text=' + encodeURIComponent(plain)
                 + '&hot=' + ((_dpSegCardOn(jav) || _dpEndCardOn(jav)) ? '1' : '0')
                 + '&bubble=' + (_dpBubbleOn(jav) ? '1' : '0')
                 + '&segcard=' + (_dpSegCardOn(jav) ? '1' : '0')
                 + '&endcard=' + (_dpEndCardOn(jav) ? '1' : '0')
                 + '&theme=' + _dpTheme(jav);
        var r = '';
        try {
            var _resp = jav.post(_dpSrv() + '/qqdp/inline', body,
                {"Content-Type": "application/x-www-form-urlencoded;charset=utf-8"});
            r = String(_resp.body() || '');
        } catch (e4) {
            try {
                r = String(jav.post(_dpSrv() + '/qqdp/inline', body, {}).body() || '');
            } catch (e5) { r = ''; }
        }
        if (r.length > 80 && r.indexOf('qqShowCmt(') >= 0) {
            var n = (r.match(/qqShowCmt\(/g) || []).length;
            if (_DP_DEBUG_OK) _dpToast(jav, '段评:服务器通道' + n + '个');
            return r;
        }
        if (!_DP_LAST_FAIL) {
            _DP_LAST_FAIL = '服务器:未注入(len=' + r.length
                + (plain && r === plain ? ' 原样返回' : '') + ')';
        }
        return '';
    } catch (e) {
        if (!_DP_LAST_FAIL) _DP_LAST_FAIL = '服务器:异常 ' + e;
        return '';
    }
}

function __dpInject(txt, nm, au, cn, jav, ck, bko, chapter) {
    var t = String(txt == null ? '' : txt);
    function _reIllu(x) {
        try { return __dpIllu(x, bko, chapter, jav); } catch (eI2) { return x; }
    }
    try {
        t = _dpFitImgs(t);
        try { t = __dpIllu(t, bko, chapter, jav); } catch (eIllu) {}  
        _dpSetCtx(jav, bko, _dpScopeChapter());
        var bubbleOn = true, segCardOn = true, endCardOn = true;
        try { bubbleOn = _dpBubbleOn(jav); } catch (eSO) {}
        try { segCardOn = _dpSegCardOn(jav); } catch (eSO2) {}
        try { endCardOn = _dpEndCardOn(jav); } catch (eHO2) {}
        if (bko && nm) { try { _dpRegBook(_dpSrcOf(jav), nm, bko.bookUrl ? String(bko.bookUrl) : ''); } catch (eR0) {} }
        if (!bubbleOn && !segCardOn && !endCardOn) { return t; }
        if (t.length < 80) return t;
        if (t.indexOf('qqShowCmt(') >= 0) return t;
        if (t.indexOf('</p>') < 0 && /<p[\s>]/i.test(t)) {
            t = t.replace(/<p([^>]*)>/gi, '</p><p$1>').replace(/^(<\/p>)+/i, '') + '</p>';
        }
        nm = _dpT2S(jav, nm);
        au = _dpT2S(jav, au);
        cn = _dpT2S(jav, cn);
        if (!cn) {
            try {
                var mm = t.replace(/^[\s\u3000]+/, '').match(/^(第[0-9一二三四五六七八九十百千两零]{1,12}[章节回卷集篇][^\n]{0,24})/);
                if (mm) cn = mm[1];
            } catch (e0) {}
        }
        if (!nm || !cn) { _dpToast(jav, '段评:缺名 nm=' + nm + ' cn=' + cn); return t; }

        _DP_NET_ERR = '';
        var srv = _dpInjectServer(t, nm, au, cn, jav);
        if (srv) return _reIllu(srv);

        _dpToast(jav, '段评:服务器未取到(' + _DP_LAST_FAIL + ')');
        return _reIllu(t);
    } catch (e) { _dpToast(jav, '段评:异常 ' + e); return txt; }
}


var _JJ_SERVER = 'http://43.139.147.103:8070';  
function _dpDpSrv(ovr){
    try {
        var s = _dpSrcOf(_dpJv());
        if (s && typeof s.get === 'function') {
            var v = String(s.get(ovr || 'jj_server') || '');
            if (v) return v.replace(/\/+$/, '');
        }
    } catch (e) {}
    return _JJ_SERVER;
}
function _dpDpShow(jv, url) {
    var cfg = JSON.stringify({
        "expandedCornersRadius": 20, "dismissOnTouchOutside": true, "isDraggable": true,
        "shouldDimBackground": true, "backgroundDimAmount": 0.5, "hardwareAccelerated": true,
        "isNestedScrollingEnabled": true, "isGestureInsetBottomIgnored": true,
        "setFitToContents": true, "isHideable": true, "heightPercentage": 0.8
    });
    var html = '';
    try { html = String(jv.ajax(url) || ''); } catch (eA) {}
    if (html && html.indexOf('<!DOCTYPE html>') >= 0) {
        try { jv.showBrowser(url, html, '', cfg); return true; } catch (eB) {}
    }
    try { jv.showBrowser(url, null, null, cfg); return true; } catch (eB2) {}
    try { jv.startBrowser(url, '段评'); } catch (eC) {}
    return false;
}
function _jjSrv() {
    try { return _dpDpSrv('jj_server'); } catch (e) { return _JJ_SERVER; }
}
function jjShowCmt(nid, cid, para, cnt, pt64) {
    var jv = null;
    try { if (this && this.java) jv = this.java; } catch (e) {}
    if (!jv) jv = _dpJv();
    if (!jv) return;
    try {
        nid = _dpFlat(nid); cid = _dpFlat(cid); para = _dpFlat(para);
        if (!nid || !cid) { try { jv.toast('段评参数缺失'); } catch (e0) {} return; }
        if (!para) para = '1';
        var tq = '';
        try { tq = encodeURIComponent(_dpFlat(pt64)); } catch (eT) {}
        var host = _JJ_SERVER;
        try { host = _jjSrv(); } catch (eH) {}
        _dpDpShow(jv, host + '/jj/review?nid=' + encodeURIComponent(nid) +
                       '&cid=' + encodeURIComponent(cid) +
                       '&para=' + encodeURIComponent(para) +
                       '&size=50&fmt=html' + (tq ? '&pt=' + tq : ''));
    } catch (eAll) {
        try { jv.toast('段评打开失败：' + eAll); } catch (eT2) {}
    }
}
function sqShowCmt(bid, cid, para, cnt, pt64) {
    var jv = null;
    try { if (this && this.java) jv = this.java; } catch (e) {}
    if (!jv) jv = _dpJv();
    if (!jv) return;
    bid = _dpFlat(bid); cid = _dpFlat(cid); para = _dpFlat(para);
    if (!bid || !cid) { try { jv.toast('段评参数缺失'); } catch (e0) {} return; }
    if (!para) para = 'p001';
    var pq = encodeURIComponent(para);
    var tq = '';
    try { tq = encodeURIComponent(_dpFlat(pt64)); } catch (eT) {}
    _dpDpShow(jv, _JJ_SERVER + '/shuqi/review?bid=' + encodeURIComponent(bid) +
                   '&cid=' + encodeURIComponent(cid) +
                   '&pid=' + pq + '&para=' + pq + '&size=50&fmt=html' +
                   (tq ? '&pt=' + tq : ''));
}

function qqShowCmt(bid, cid, segId, csrf, q, qdBid, qdCid, name, author, ch) {
    var jv = null;
    try { if (this && this.java) jv = this.java; } catch (e) {}
    if (!jv) jv = _dpJv();          
    if (!jv) return;
    bid = _dpFlat(bid); cid = _dpFlat(cid); segId = _dpFlat(segId); csrf = _dpFlat(csrf);
    q = _dpFlat(q); qdBid = _dpFlat(qdBid); qdCid = _dpFlat(qdCid);
    name = _dpFlat(name); author = _dpFlat(author); ch = _dpFlat(ch);
